    "vi.vi-ed-standard.name": "Standard Edition",
    "vi.vi-ed-standard.priceBR": "R$ 449,90 (precio anunciado en la reserva brasileña)",
    "vi.vi-ed-standard.blurb": "El juego completo en Leonida, para PS5 o Xbox Series X|S.",
